73	impl TerminalWorkflowDisplay {
74	    /// Construct a new terminal workflow display.
75	    pub fn new(surface: Arc<TerminalSurface>, mode: OutputMode) -> Self {
76	        let theme = if crate::ui::should_use_colors() {
77	            BivvyTheme::new()
78	        } else {
79	            BivvyTheme::plain()
80	        };
81	        Self {
82	            surface,
83	            theme,
84	            mode,
85	            pinned: None,
86	        }
87	    }
88	
89	    /// Format the bar message string with bracket bar + counts.
90	    fn format_bar(theme: &BivvyTheme, current: usize, total: usize, elapsed: Duration) -> String {
91	        let filled = current
92	            .checked_mul(16)
93	            .and_then(|v| v.checked_div(total))
94	            .unwrap_or(0);
95	        let empty = 16usize.saturating_sub(filled);
96	        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
97	        format!(
98	            "\n{} {}/{} steps {} {}",
99	            theme.info.apply_to(format!("[{}]", bar)),
100	            current,
101	            total,
102	            theme.dim.apply_to("·"),
103	            theme
104	                .duration
105	                .apply_to(format!("{} elapsed", format_duration(elapsed))),
106	        )
107	    }
108	}
