110	impl WorkflowDisplay for TerminalWorkflowDisplay {
111	    fn show_run_header(&mut self, hdr: &RunHeader) {
112	        if !self.mode.shows_status() {
113	            return;
114	        }
115	        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
116	        self.surface.println(&format!(
117	            "\n{} {} {} {} {} {} {}\n",
118	            self.theme.header.apply_to("⛺"),
119	            self.theme.highlight.apply_to(&hdr.app_name),
120	            self.theme.dim.apply_to(format!("v{}", hdr.version)),
121	            self.theme.dim.apply_to("·"),
122	            self.theme
123	                .dim
124	                .apply_to(format!("{} workflow", hdr.workflow)),
125	            self.theme
126	                .dim
127	                .apply_to(format!("· {} {}", hdr.step_count, step_label)),
128	            self.theme.dim.apply_to(format!("· env: {}", hdr.env_name)),
129	        ));
130	    }
131	
132	    fn start_progress(&mut self, total: usize) {
133	        if !self.mode.shows_status() {
134	            return;
135	        }
136	        let bar = ProgressBar::new(total as u64);
137	        bar.set_style(ProgressStyle::default_bar().template("{msg}").unwrap());
138	        bar.set_message(Self::format_bar(&self.theme, 0, total, Duration::ZERO));
139	        self.pinned = Some(self.surface.pin_bottom(bar));
140	    }
141	
142	    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
143	        if !self.mode.shows_status() {
144	            return;
145	        }
146	        if let Some(p) = &self.pinned {
147	            p.set_message(Self::format_bar(&self.theme, current, total, elapsed));
148	        }
149	    }
150	
151	    fn finish_progress(&mut self) {
152	        // Drop clears the bar.
153	        self.pinned = None;
154	    }
155	
156	    fn show_run_summary(&mut self, summary: &RunSummary) {
157	        if !self.mode.shows_status() {
158	            return;
159	        }
160	
161	        let b = &self.theme.border;
162	        let mut lines = vec![
163	            String::new(),
164	            format!(
165	                "{} {}",
166	                b.apply_to("┌─"),
167	                b.apply_to("Summary ──────────────────────────")
168	            ),
169	        ];
170	
171	        for step in &summary.step_results {
172	            let icon = step.status.styled(&self.theme);
173	            let duration_str = step.duration.map(format_duration).unwrap_or_default();
174	            let detail_str = step.detail.as_deref().unwrap_or("");
175	
176	            let right_side = if !duration_str.is_empty() {
177	                self.theme.duration.apply_to(duration_str).to_string()
178	            } else if !detail_str.is_empty() {
179	                self.theme.dim.apply_to(detail_str).to_string()
180	            } else {
181	                String::new()
182	            };
183	
184	            lines.push(format!(
185	                "{} {} {:<20} {}",
186	                b.apply_to("│"),
187	                icon,
188	                step.name,
189	                right_side,
190	            ));
191	        }
192	
193	        let satisfied_part = if summary.steps_satisfied > 0 {
194	            format!(
195	                " {} {} already satisfied",
196	                self.theme.dim.apply_to("·"),
197	                summary.steps_satisfied,
198	            )
199	        } else {
200	            String::new()
201	        };
202	        lines.push(
203	            b.apply_to("├────────────────────────────────────")
204	                .to_string(),
205	        );
206	        lines.push(format!(
207	            "{} Total: {} {} {} run {} {} skipped{}",
208	            b.apply_to("│"),
209	            self.theme
210	                .duration
211	                .apply_to(format_duration(summary.total_duration)),
212	            self.theme.dim.apply_to("·"),
213	            summary.steps_run,
214	            self.theme.dim.apply_to("·"),
215	            summary.steps_skipped,
216	            satisfied_part,
217	        ));
218	        lines.push(
219	            b.apply_to("└────────────────────────────────────")
220	                .to_string(),
221	        );
222	
223	        for line in &lines {
224	            self.surface.println(line);
225	        }
226	    }
227	
228	    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
229	        Box::new(TerminalStepDisplay::new(
230	            Arc::clone(&self.surface),
231	            self.mode,
232	            index,
233	            total,
234	        ))
235	    }
236	
237	    fn message(&mut self, msg: &str) {
238	        if self.mode.shows_status() {
239	            self.surface.println(msg);
240	        }
241	    }
242	
243	    fn hint(&mut self, hint: &str) {
244	        if !self.mode.shows_status() {
245	            return;
246	        }
247	        self.surface
248	            .println(&self.theme.hint.apply_to(hint).to_string());
249	        self.surface.println("");
250	    }
251	}
