281	    fn show_run_header(&mut self, hdr: &RunHeader) {
282	        if !self.mode.shows_status() {
283	            return;
284	        }
285	        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
286	        println!(
287	            "\n⛺ {} v{} · {} workflow · {} {} · env: {}\n",
288	            hdr.app_name, hdr.version, hdr.workflow, hdr.step_count, step_label, hdr.env_name,
289	        );
