318	    fn show_run_summary(&mut self, summary: &RunSummary) {
319	        if !self.mode.shows_status() {
320	            return;
321	        }
322	
323	        println!();
324	        println!("  ┌─ Summary ──────────────────────────");
325	
326	        for step in &summary.step_results {
327	            let icon = step.status.icon();
328	            let duration_str = step.duration.map(format_duration).unwrap_or_default();
329	            let detail_str = step.detail.as_deref().unwrap_or("");
330	
331	            let right_side = if !duration_str.is_empty() {
332	                duration_str
333	            } else if !detail_str.is_empty() {
334	                detail_str.to_string()
335	            } else {
336	                String::new()
337	            };
338	
339	            println!("  │ {} {:<20} {}", icon, step.name, right_side);
340	        }
341	
342	        println!("  ├────────────────────────────────────");
343	        let satisfied_part = if summary.steps_satisfied > 0 {
344	            format!(" · {} already satisfied", summary.steps_satisfied)
345	        } else {
346	            String::new()
347	        };
348	        println!(
349	            "  │ Total: {} · {} run · {} skipped{}",
350	            format_duration(summary.total_duration),
351	            summary.steps_run,
352	            summary.steps_skipped,
353	            satisfied_part,
354	        );
355	        println!("  └────────────────────────────────────");
356	        // No trailing "Setup complete!" / "Setup failed" line — see the
357	        // matching note in `TerminalWorkflowDisplay::show_run_summary`.
358	    }
