58	impl MockUI {
59	    /// Create a new MockUI with Normal output mode.
60	    pub fn new() -> Self {
61	        Self {
62	            mode: OutputMode::Normal,
63	            ..Default::default()
64	        }
65	    }
66	
67	    /// Create a new MockUI with a specific output mode.
68	    pub fn with_mode(mode: OutputMode) -> Self {
69	        Self {
70	            mode,
71	            ..Default::default()
72	        }
73	    }
74	
75	    /// Set a response for a prompt key.
76	    ///
77	    /// When `prompt()` is called with this key, it returns the configured response.
78	    pub fn set_prompt_response(&mut self, key: &str, response: &str) {
79	        self.prompt_responses
80	            .insert(key.to_string(), response.to_string());
81	    }
82	
83	    /// Set multiple prompt responses at once.
84	    pub fn with_prompt_responses(mut self, responses: HashMap<String, String>) -> Self {
85	        self.prompt_responses = responses;
86	        self
87	    }
88	
89	    /// Queue multiple responses for the same prompt key.
90	    ///
91	    /// Responses are returned in order. After the queue is exhausted,
92	    /// falls back to `set_prompt_response` or defaults.
93	    pub fn queue_prompt_responses(&mut self, key: &str, responses: Vec<&str>) {
94	        let queue = responses.into_iter().map(|s| s.to_string()).collect();
95	        self.prompt_queues.insert(key.to_string(), queue);
96	    }
97	
98	    /// Set a default response for any prompt key not explicitly configured.
99	    ///
100	    /// Useful when a workflow may prompt with unpredictable keys (e.g., recovery
101	    /// prompts whose key includes the step name, which depends on template detection).
102	    pub fn set_default_prompt_response(&mut self, response: &str) {
103	        self.default_prompt_response = Some(response.to_string());
104	    }
105	
106	    /// Set whether this mock behaves as interactive.
107	    pub fn set_interactive(&mut self, interactive: bool) {
108	        self.interactive = interactive;
109	    }
110	
111	    /// Get all captured messages.
112	    pub fn messages(&self) -> &[String] {
113	        &self.messages
114	    }
115	
116	    /// Get all captured success messages.
117	    pub fn successes(&self) -> &[String] {
118	        &self.successes
119	    }
120	
121	    /// Get all captured warning messages.
122	    pub fn warnings(&self) -> &[String] {
123	        &self.warnings
124	    }
125	
126	    /// Get all captured error messages.
127	    pub fn errors(&self) -> &[String] {
128	        &self.errors
129	    }
130	
131	    /// Get all captured headers.
132	    pub fn headers(&self) -> &[String] {
133	        &self.headers
134	    }
135	
136	    /// Get all captured hints.
137	    pub fn hints(&self) -> &[String] {
138	        &self.hints
139	    }
140	
141	    /// Get all captured progress updates.
142	    pub fn progress(&self) -> &[(usize, usize)] {
143	        &self.progress
144	    }
145	
146	    /// Get all spinner messages that were started.
147	    pub fn spinners(&self) -> &[String] {
148	        &self.spinners
149	    }
150	
151	    /// Get all prompts that were shown (by key).
152	    pub fn prompts_shown(&self) -> &[String] {
153	        &self.prompts_shown
154	    }
155	
156	    /// Check if a specific message was shown.
157	    pub fn has_message(&self, msg: &str) -> bool {
158	        self.messages.iter().any(|m| m.contains(msg))
159	    }
160	
161	    /// Check if a specific success was shown.
162	    pub fn has_success(&self, msg: &str) -> bool {
163	        self.successes.iter().any(|m| m.contains(msg))
164	    }
165	
166	    /// Check if a specific error was shown.
167	    pub fn has_error(&self, msg: &str) -> bool {
168	        self.errors.iter().any(|m| m.contains(msg))
169	    }
170	
171	    /// Check if a specific hint was shown.
172	    pub fn has_hint(&self, msg: &str) -> bool {
173	        self.hints.iter().any(|m| m.contains(msg))
174	    }
175	
176	    /// Check if a specific warning was shown.
177	    pub fn has_warning(&self, msg: &str) -> bool {
178	        self.warnings.iter().any(|m| m.contains(msg))
179	    }
180	
181	    /// Get all captured error blocks as (command, output, hint, indent).
182	    pub fn error_blocks(&self) -> &[(String, String, Option<String>, usize)] {
183	        &self.error_blocks
184	    }
185	
186	    /// Clear all captured interactions.
187	    pub fn clear(&mut self) {
188	        self.messages.clear();
189	        self.successes.clear();
190	        self.warnings.clear();
191	        self.errors.clear();
192	        self.headers.clear();
193	        self.hints.clear();
194	        self.progress.clear();
195	        self.spinners.clear();
196	        self.error_blocks.clear();
197	        self.prompts_shown.clear();
198	    }
199	}
