201	impl OutputWriter for MockUI {
202	    fn message(&mut self, msg: &str) {
203	        self.messages.push(msg.to_string());
204	    }
205	
206	    fn success(&mut self, msg: &str) {
207	        self.successes.push(msg.to_string());
208	    }
209	
210	    fn warning(&mut self, msg: &str) {
211	        self.warnings.push(msg.to_string());
212	    }
