354	/// Status of a mock spinner when finished.
355	#[derive(Debug, Clone, Copy, PartialEq)]
356	pub enum SpinnerStatus {
357	    /// Finished successfully.
358	    Success,
359	    /// Finished with error.
360	    Error,
361	    /// Finished as skipped.
362	    Skipped,
363	}
