use crate::error::Result;

use super::{Prompt, PromptResult};

/// Prompting strategy for the runner display layer.
///
/// Separates the mechanism of showing prompts (terminal allocation,
/// dialoguer calls) from the display implementation, so the display
/// layer can be tested without a real terminal.
pub trait DisplayPrompter {
    /// Present a prompt to the user and return their response.
    fn prompt(&self, prompt: &Prompt) -> Result<PromptResult>;
}

/// Terminal prompter that delegates to `dialoguer` via `console::Term`.
pub struct TerminalDisplayPrompter;

impl DisplayPrompter for TerminalDisplayPrompter {
    fn prompt(&self, _prompt: &Prompt) -> Result<PromptResult> {
        todo!()
    }
}

