//! Display-layer prompting abstraction.
//!
//! [`DisplayPrompter`] separates the mechanism of showing prompts
//! (terminal allocation, dialoguer calls) from the display
//! implementation. Production code uses [`TerminalDisplayPrompter`];
//! tests use [`MockDisplayPrompter`].

use crate::error::Result;

use super::{Prompt, PromptResult, PromptType};

/// Prompting strategy for the runner display layer.
///
/// Separates the mechanism of showing prompts (terminal allocation,
/// dialoguer calls) from the display implementation, so the display
/// layer can be tested without a real terminal.
pub trait DisplayPrompter {
    /// Present a prompt to the user and return their response.
    fn prompt(&self, prompt: &Prompt) -> Result<PromptResult>;
}

/// Terminal prompter that delegates to `dialoguer` via `console::Term`.
///
/// Creates a fresh `console::Term::stdout()` for each prompt and
/// delegates to [`super::prompt_user`]. This is the production
/// implementation used by interactive terminal sessions.
pub struct TerminalDisplayPrompter;

impl DisplayPrompter for TerminalDisplayPrompter {
    fn prompt(&self, prompt: &Prompt) -> Result<PromptResult> {
        let term = console::Term::stdout();
        super::prompt_user(prompt, &term)
    }
}

/// Mock prompter for testing.
///
/// Returns the prompt's default value when available, or an empty
/// string otherwise. Mirrors the fallback behavior of
/// `NonInteractiveStepDisplay`.
pub struct MockDisplayPrompter;

impl DisplayPrompter for MockDisplayPrompter {
    fn prompt(&self, prompt: &Prompt) -> Result<PromptResult> {
        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
        if let Some(default) = &prompt.default {
            if is_multiselect {
                let values: Vec<String> =
                    default.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(PromptResult::Strings(values));
            }
            return Ok(PromptResult::String(default.clone()));
        }
        if is_multiselect {
            return Ok(PromptResult::Strings(Vec::new()));
        }
        Ok(PromptResult::String(String::new()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ui::{PromptOption, PromptType};

    fn make_prompt(key: &str, prompt_type: PromptType, default: Option<&str>) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: "Test question?".to_string(),
            prompt_type,
            default: default.map(String::from),
        }
    }

    #[test]
    fn mock_prompter_returns_default_for_input() {
        let prompter = MockDisplayPrompter;
        let prompt = make_prompt("test", PromptType::Input, Some("default_val"));
        let result = prompter.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "default_val");
    }

    #[test]
    fn mock_prompter_returns_empty_without_default() {
        let prompter = MockDisplayPrompter;
        let prompt = make_prompt("test", PromptType::Input, None);
        let result = prompter.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "");
    }

    #[test]
    fn mock_prompter_returns_default_for_multiselect() {
        let prompter = MockDisplayPrompter;
        let prompt = make_prompt(
            "multi",
            PromptType::MultiSelect {
                options: vec![
                    PromptOption {
                        label: "A".to_string(),
                        value: "a".to_string(),
                    },
                    PromptOption {
                        label: "B".to_string(),
                        value: "b".to_string(),
                    },
                ],
            },
            Some("a,b"),
        );
        let result = prompter.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "a,b");
    }

    #[test]
    fn mock_prompter_returns_empty_multiselect_without_default() {
        let prompter = MockDisplayPrompter;
        let prompt = make_prompt(
            "multi",
            PromptType::MultiSelect { options: vec![] },
            None,
        );
        let result = prompter.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "");
    }

    #[test]
    fn display_prompter_is_object_safe() {
        let prompter: Box<dyn DisplayPrompter> = Box::new(MockDisplayPrompter);
        let _ = prompter;
    }
}

